"""Small boolean WPL authoring subset, lowered to the existing SKI kernel.

Church boolean lowering adapted from Warrant impl/ski_policy.py (MIT,
Copyright 2025–2026 s0fractal). No policy runtime is added to verification.
"""
import re
from dataclasses import dataclass

from . import kernel as k
from .canonical import canon, decode
from .checks import run_check

MAX_SOURCE_BYTES = 8192
MAX_TOKENS = 256
DEFAULT_MAX_ATP = 100_000
TOKEN = re.compile(r'\s+|#[^\n]*|&&|\|\||[!():=]|[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*')
RESERVED = {'fact', 'check', 'bool', 'true', 'false'}


class PolicyError(ValueError):
    """Unsupported or invalid author input; no record should be emitted."""


class CompileIncomplete(PolicyError):
    """Valid source did not finish; distinct from malformed source."""


class CompilerBug(RuntimeError):
    """Compiler output disagrees with the source interpreter or emission gate."""


def parse(source, inputs=None):
    if not isinstance(source, str):
        raise PolicyError('source must be text')
    try:
        if len(source.encode('utf-8')) > MAX_SOURCE_BYTES:
            raise PolicyError('source exceeds 8192 bytes')
    except UnicodeError as exc:
        raise PolicyError('source contains invalid Unicode') from exc
    tokens, pos = [], 0
    while pos < len(source):
        m = TOKEN.match(source, pos)
        if not m:
            raise PolicyError(f'unsupported token at character {pos}')
        text = m.group()
        if not text.isspace() and not text.startswith('#'):
            tokens.append(text)
        pos = m.end()
    if len(tokens) > MAX_TOKENS:
        raise PolicyError('policy exceeds 256 tokens')
    cursor = 0
    facts, used = {}, set()
    def peek():
        return tokens[cursor] if cursor < len(tokens) else None
    def take(expected=None):
        nonlocal cursor
        token = peek()
        if token is None or (expected is not None and token != expected):
            raise PolicyError(f'expected {expected or "expression"}, got {token!r}')
        cursor += 1
        return token
    while peek() == 'fact':
        take('fact'); name = take()
        if name in RESERVED or re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*', name) is None:
            raise PolicyError('invalid fact name')
        if name in facts:
            raise PolicyError('duplicate fact: ' + name)
        take(':'); take('bool')
        if inputs is None:
            take('='); value = take()
            if value not in ('true', 'false'):
                raise PolicyError('boolean facts require true or false')
            facts[name] = value == 'true'
        else:
            if name not in inputs or type(inputs[name]) is not bool:
                raise PolicyError('missing or non-boolean fact: ' + name)
            facts[name] = inputs[name]
    take('check')
    def atom(depth):
        if depth > 32:
            raise PolicyError('expression nesting exceeds 32')
        if peek() == '!':
            take('!')
            return ('not', atom(depth + 1))
        if peek() == '(':
            take('('); result = disjunction(depth + 1); take(')')
            return result
        name = take()
        if name in ('true', 'false'):
            return ('const', name == 'true')
        if name not in facts:
            raise PolicyError('unknown fact: ' + name)
        used.add(name)
        return ('fact', name)
    def conjunction(depth):
        expr = atom(depth)
        while peek() == '&&':
            take('&&'); expr = ('and', expr, atom(depth))
        return expr
    def disjunction(depth):
        expr = conjunction(depth)
        while peek() == '||':
            take('||'); expr = ('or', expr, conjunction(depth))
        return expr
    expression = disjunction(0)
    if peek() is not None:
        raise PolicyError('expected exactly one check and no trailing tokens')
    if used != set(facts):
        raise PolicyError('unused facts: ' + ', '.join(sorted(set(facts) - used)))
    if inputs is not None and set(inputs) != set(facts):
        raise PolicyError('facts must exactly match the rule declarations')
    return expression, facts


def interpret(expr, facts):
    tag = expr[0]
    if tag == 'const': return expr[1]
    if tag == 'fact': return facts[expr[1]]
    if tag == 'not': return not interpret(expr[1], facts)
    if tag == 'and': return interpret(expr[1], facts) and interpret(expr[2], facts)
    if tag == 'or': return interpret(expr[1], facts) or interpret(expr[2], facts)
    raise CompilerBug('unknown expression')


def lower(expr, facts):
    true, false = ('thunk', k.K_H), ('thunk', k.FALSE_H)
    def apply(f, a, b): return ('app', ('app', f, a), b)
    tag = expr[0]
    if tag == 'const': return true if expr[1] else false
    if tag == 'fact': return true if facts[expr[1]] else false
    if tag == 'not': return apply(lower(expr[1], facts), false, true)
    if tag == 'and': return apply(lower(expr[1], facts), lower(expr[2], facts), false)
    if tag == 'or': return apply(lower(expr[1], facts), true, lower(expr[2], facts))
    raise CompilerBug('unknown expression')


@dataclass
class CompiledPolicy:
    check: dict
    objects: dict
    value: bool
    atp_spent: int


def compile_source(source, *, max_atp=DEFAULT_MAX_ATP, facts=None, limits=None):
    if type(max_atp) is not int or not 0 <= max_atp <= k.VERIFIER_LIMITS['max_atp']:
        raise PolicyError('compile limit must be an integer within the verifier ATP ceiling')
    if facts is not None and (not isinstance(facts, dict)
                              or not all(isinstance(n, str) and type(v) is bool for n, v in facts.items())):
        raise PolicyError('facts must be an object of boolean values')
    expr, facts = parse(source, facts)
    value = interpret(expr, facts)
    term = lower(expr, facts)
    objects = {k.FALSE_H: k.FALSE_BYTES}
    def materialize(t):
        if t[0] == 'app':
            materialize(t[1]); materialize(t[2])
            raw = k.term_bytes(t)
            objects[k.sha(raw)] = raw
    materialize(term)
    h = k.term_hash(term)
    evaluator_limits = dict(k.VERIFIER_LIMITS)
    if limits is not None:
        evaluator_limits.update(limits)
    receipt = k.eval_receipt(h, max_atp, objects, evaluator_limits)
    if receipt.exit != 'normal_form':
        raise CompileIncomplete('policy did not finish within the compile budget')
    expected_value_hash = k.K_H if value else k.FALSE_H
    if receipt.result_hash != expected_value_hash:
        raise CompilerBug('SKI result disagrees with source interpreter')
    # ALWAYS expect TRUE: compiling a false predicate must not pin FALSE and
    # thereby turn a false policy into an accepted computation claim.
    check = decode(canon(dict(term=h.hex(), atp=receipt.atp_spent,
                             expect=k.K_H.hex(), exit='normal_form',
                             environment=sorted(h.hex() for h in objects))))
    outcome = run_check(check, objects, limits=limits)
    if (outcome.result_hash != expected_value_hash.hex() or outcome.exit != 'normal_form'
            or outcome.atp_spent != receipt.atp_spent
            or outcome.verdict != ('pass' if value else 'fail')):
        raise CompilerBug('serialized check failed exact-budget re-execution')
    return CompiledPolicy(check, objects, value, receipt.atp_spent)

sources.invariants.py:
"""Finite input/output properties, not temporal or universal program invariants.

Discovery generates hypotheses; checking recomputes the complete finite table
through the existing SKI + independent-oracle gate. No saved report is trusted.
"""
from . import lab
from .canonical import canon, decode, exact, record_hash, InvalidRecord


def _claim(doc, parent, claim):
    claim = decode(canon(claim))
    exact(claim, ('parent', 'property'))
    record_hash(claim['parent'])
    if claim['parent'] != parent:
        raise InvalidRecord('invariant parent mismatch')
    prop = claim['property']
    if not isinstance(prop, dict):
        raise InvalidRecord('property must be an object')
    if prop.get('kind') == 'constant':
        exact(prop, ('kind', 'value'))
        if type(prop['value']) is not bool:
            raise InvalidRecord('constant value must be boolean')
    elif prop.get('kind') in ('independent', 'monotone'):
        exact(prop, ('kind', 'input'))
        if not isinstance(prop['input'], str) or prop['input'] not in doc['inputs']:
            raise InvalidRecord('unknown property input')
    else:
        raise InvalidRecord('unsupported finite property')
    return claim


def _table(raw, doc):
    # A self-comparison reuses both parsers, receipts and coverage controls.
    # Cost admission is irrelevant: equivalent/not_strictly_cheaper still gives
    # a complete checked table. Any constructed successor is deliberately ignored.
    verified, _ = lab.verify_transition(raw, {'parent':lab.identity(raw), 'candidate':doc['rule']})
    if verified['status'] != 'equivalent':
        status = 'incomplete' if verified['status'] == 'incomplete' else 'checker_error'
        return None, dict(status=status, reason=verified.get('reason', 'self-comparison disagreed'))
    rows = [dict(input=r['input'], **r['parent']) for r in verified['rows']]
    # Check the received internal table explicitly, rather than trusting a label.
    if len(rows) != 2**len(doc['inputs']):
        return None, dict(status='checker_error', reason='invariant table incomplete')
    for index, row in enumerate(rows):
        expected = {n:bool(index & (1 << (len(doc['inputs'])-j-1))) for j,n in enumerate(doc['inputs'])}
        if row['input'] != expected or type(row['value']) is not bool:
            return None, dict(status='checker_error', reason='invariant table order or values invalid')
    return rows, None


def _assess(doc, rows, claim):
    prop = claim['property']
    result = dict(claim=claim, status='established', checked=0)
    if prop['kind'] == 'constant':
        expected_checks = len(rows)
        for row in rows:
            result['checked'] += 1
            if row['value'] != prop['value']:
                result.update(status='counterexample', witness=[row])
                return result
    else:
        mask = 1 << (len(doc['inputs']) - doc['inputs'].index(prop['input']) - 1)
        expected_checks = len(rows)//2
        for index, low in enumerate(rows):
            if index & mask:
                continue
            high = rows[index | mask]
            result['checked'] += 1
            violates = (low['value'] != high['value'] if prop['kind'] == 'independent'
                        else low['value'] and not high['value'])
            if violates:
                result.update(status='counterexample', witness=[low, high])
                return result
    if result['checked'] != expected_checks:
        result.update(status='checker_error', reason='property obligations not fully checked')
    return result


def verify_claim(raw, claim):
    doc = lab.inspect_world(raw)
    claim = _claim(doc, lab.identity(raw), claim)  # Validate even when budget is too small.
    report = dict(parent=lab.identity(raw), runtime_digest=lab.runtime_digest(doc['sources']), claim=claim)
    rows, failure = _table(raw, doc)
    if failure:
        return dict(report, **failure)
    report.update(_assess(doc, rows, claim))
    return dict(report, table=rows, table_digest=lab.identity(canon(rows)), total_rows=len(rows))


def discover(raw):
    doc = lab.inspect_world(raw)
    parent = lab.identity(raw)
    report = dict(parent=parent, runtime_digest=lab.runtime_digest(doc['sources']), results=[])
    rows, failure = _table(raw, doc)
    if failure:
        return dict(report, **failure)
    properties = [dict(kind='constant', value=False), dict(kind='constant', value=True)]
    for name in doc['inputs']:
        properties.extend([dict(kind='independent', input=name), dict(kind='monotone', input=name)])
    for prop in properties:
        claim = _claim(doc, parent, dict(parent=parent, property=prop))
        verdict = _assess(doc, rows, claim)
        report['results'].append(verdict)
        if verdict['status'] == 'checker_error':
            return dict(report, status='checker_error', reason=verdict['reason'])
    return dict(report, status='complete', table=rows, table_digest=lab.identity(canon(rows)),
                total_rows=len(rows), hypotheses=len(properties))

